    guide_text_640531df048ef5cf: "Filters и More filters",
    guide_text_12f8a37862fd6f82: "Сужают список по доступным для него признакам: ключевому слову, ведомству, месту, этапу, диапазону дат или сумме",
    guide_text_fe8f1030c739def9: "Более узкий список, сохранённый в адресе",
    guide_text_85c956e922099f70: "Переводит в Following с открытым конструктором отслеживания",
    guide_text_6c012172e6534a9a: "Ничего не запущено. Вам ещё предстоит просмотреть и подтвердить отслеживание",
    guide_text_79086734c2aba90b: "Export {name_a}, Export Excel и Print",
    guide_text_d6ac3ceab46ee1cc: "Позволяют взять с собой просматриваемый список",
    guide_text_88e0f5d3c8f9ccaf: "Файл или печатная страница списка с текущими фильтрами",
    guide_text_c74ea9dc9cd25b58: "Что он делает",
    guide_text_358a3c3e3e8eb66f: "Что вы получаете",
    guide_text_da0cd9290737dcc1: "Доступные фильтры зависят от свойств вида записей: сумма относится к контрактам, этап — к заседаниям. Сам список определяет, какие фильтры в нём доступны.",
    guide_text_75ed6f167c596676: "Поиск и списки обзора собирают результаты в браузере и требуют {name_a}. Страницы отдельных записей и все страницы этого руководства — нет.",
    guide_text_36c7b341bd7d8ab9: "Отслеживание темы",
    guide_text_4232fb857294967d: "Вкладка, где отслеживание создаётся из темы и места",
