    guide_text_dbaf2ebdb2d6f272: "Общественные советы на {name_a}",
    guide_text_9439fe6659a056a1: "Словарь терминов {name_a}",
    guide_text_fbbb4d3a7f19fd66: "Добавьте даты в календарь · {name_a}",
    guide_text_90934486a858f35e: "Добавьте одно городское событие или подпишитесь на весь список, точно понимая, что сделали и чего от этого ждать.",
