    guide_text_feb8caca5a9f10ca: "Открыть Now",
    guide_text_621fa3b9bef5b00f: "Прочитайте проект землепользования · {name_a}",
    guide_text_dc469d89bd5f156e: "Откройте проект, прочитайте, какой орган действует следующим и когда это известно, и найдите настоящие поданные документы на городском портале.",
    guide_text_b23352fad90077be: "Проверьте текущий этап проекта, следующую опубликованную возможность и официальные документы.",
