    guide_text_39b2ec958868588f: "Обзор проектов землепользования",
    guide_text_11cf9db750f1d362: "Проверьте доказательства связи · {name_a}",
    guide_text_6468cfbf8c0cd948: "Откройте подтверждение любой связи между записями {name_a}, прочитайте утверждение и сохраните ссылку, повторно открывающую ту же панель.",
    guide_text_9ee797b2017e2770: "Проверьте связь и скопируйте ссылку для повторного открытия доказательств.",
    guide_text_067c4d6457ac8784: "Открыть связь из руководства",
    guide_text_2e438e2d299d89c0: "Посмотрите записи по состоянию на день · {name_a}",
    guide_text_df41c1bfbc7b25b1: "Отфильтруйте страницу ведомства до записей не позднее выбранного дня, поделитесь результатом и узнайте границы фильтра.",
    guide_text_db168781332100a3: "Отфильтруйте ведомство по дате и поделитесь видом или очистите его.",
    guide_text_4bf41e3e5c53d82b: "Обзор общедоступных записей Нью-Йорка по видам",
    guide_text_b04c5305e9182fb0: "Что означают даты и отсутствующие сведения",
    guide_text_45ca554361b0518c: "Открыть страницу Parks с фильтром по дню",
    guide_text_b386e5f51e61a27c: "Соберите и экспортируйте записи · {name_a}",
    guide_text_b693f56dc74c7da5: "Закрепите настоящие записи в одном исследовании, добавьте заметки, заберите файл и узнайте, где находится каждая копия и кто может её читать.",
    guide_text_416f08760b272d47: "Закрепите записи, сохраните заметки и выберите локальный экспорт или общую копию.",
