    guide_text_eaffe7e0f637492c: "Открыть своё исследование",
    guide_text_74c74f1cc51aa393: "Прочитайте бюджетный запрос и ответ · {name_a}",
    guide_text_b0f275d69c7da30a: "Найдите запрос своего общественного совета, прочитайте датированные ответы по порядку и отличите изменение ответа от изменения бюджетной метки.",
    guide_text_dfb0fb39ac572a1a: "Найдите один запрос общественного совета, прочитайте опубликованные ответы по порядку и отличите изменение ответа от изменения бюджетной метки.",
    guide_text_60bb53de31912624: "Даты и отсутствующие сведения",
