    guide_text_37429c42a853b0bc: "Определения терминов, идентификаторов и учреждений, встречающихся в записях Нью-Йорка на {name_a}, с указанием мест появления.",
    guide_text_395c88ebbaab3f7e: "Слова, встречающиеся при чтении записей {name_a}, в смысле, используемом городом и этим сайтом.",
    guide_text_af7e0253b519e305: "Сдать экзамен на государственную службу, Department of Citywide Administrative Services",
