    guide_text_984b18097f637dce: "Что делает каждый элемент {name_a}: поиск, фильтры, отслеживание, календари, ссылки и экспорт — и в каком состоянии вы остаётесь.",
    guide_text_cc0c6126eab81bfe: "Найдите распространённые элементы управления, их эффекты и создаваемые файлы или ссылки.",
