    guide_text_9e71ffac94ec5aed: "Источники и охват · {name_a}",
    guide_text_86afc28bd1adc3a6: "{name_a} повторно публикует уже опубликованное Нью-Йорком. Здесь указаны источники записей, актуальность и границы охвата.",
