    meeting_body_role_oversight: "Can question and oversee, but cannot decide",
    public_input_explainer_open: "Как работает участие общественности",
    public_input_explainer_what_html: "<p>Участие в публичной процедуре означает внесение чего-либо в официальную запись: выступление на слушании или письменный комментарий до опубликованного срока. Что эта запись делает дальше, зависит от процедуры, и каждая публикация на этом сайте указывает, какая из них применима.</p>",
    public_input_explainer_destinations_heading: "Куда попадает сказанное вами",
    public_input_explainer_destinations_html: "<ul><li><b>Публичная запись комментариев</b> — письменный комментарий, поданный в период приёма комментариев, входит в запись, которую орган обязан рассмотреть.</li><li><b>Показания на слушании</b> — сказанное вами на слушании входит в запись показаний этого слушания.</li><li><b>Стенограмма</b> — некоторые процедуры публикуют дословную запись заседания.</li><li><b>Протокол</b> — другие органы публикуют вместо этого краткое изложение произошедшего.</li><li><b>Документ решения</b> — отдельная запись, публикуемая, когда орган фиксирует решение.</li></ul><p>Некоторые процедуры также публикуют отчёт с ответом на полученные комментарии. Это одно из перечисленных назначений, и каждая публикация указывает, применимо ли оно.</p>",
    public_input_explainer_limits_heading: "Пределы участия",
    public_input_explainer_limits_html: "<p>Ответ должностного лица — это не то же самое, что запись в деле. Подача комментария или дача показаний вносит ваши слова в запись, и ни одно должностное лицо не обязано отвечать вам лично. Этот сайт такого ответа не обещает.</p><p>Подсчёт комментариев остаётся подсчётом комментариев. Орган оценивает сказанное по закону, которым он руководствуется, поэтому этот сайт не подаёт итоги комментариев как поддержку или возражение и не считает количество комментариев голосованием.</p>",
    public_input_explainer_examples_heading: "Три примера того, как это работает",
    public_input_explainer_example_hearing: "Выступите на слушании городского совета по законопроекту или направьте письменные показания.",
    public_input_explainer_example_hearing_surface: "Смотреть назначенные слушания и заседания",
    public_input_explainer_example_rule: "Прокомментируйте предлагаемое ведомством правило до опубликованного срока.",
    public_input_explainer_example_rule_surface: "Смотреть открытые периоды комментариев по правилам",
    public_input_explainer_example_contract: "Прокомментируйте предлагаемое присуждение контракта в отведённое для этого окно.",
    public_input_explainer_example_contract_surface: "Смотреть сроки комментариев по контрактам",
    public_input_explainer_official_source: "Официальный источник: {source}",
    public_input_explainer_method_summary: "Откуда взято это объяснение",
    public_input_explainer_method_html: "<p>Каждый пример выше ведёт на городскую страницу, которая его регулирует, и на раздел этого сайта, где перечислены действующие записи такого рода. Это объяснение описывает, как такие процедуры работают в общем виде. Конкретная дата, статус, цель и канал участия для каждой из них остаются в её собственной публикации, рядом со ссылкой на источник в Городском вестнике.</p>",
