    about_h_what: "Что это такое",
    about_p_what_html: "CityScroll помогает узнать, что происходит в правительстве Нью-Йорка и что можно сделать дальше. Раздел <b>Сейчас</b> показывает срочные даты, <b>Рядом с вами</b> — местные изменения, <b>Отслеживание</b> — сохранённые подписки, а <b>Обзор</b> — контракты и планы, землепользование, заседания и голосования, экзамены, продажу городской недвижимости и правила. <b>Руководство</b> объясняет, как читать запись. Сайт создан на основе официальных публикаций города, но работает независимо и не управляется и не поддерживается городом Нью-Йорком.",
    about_h_flags: "Метки и контекст — с пояснениями",
    about_h_tax_lien_formula:"Tax lien sale progression",
    about_p_tax_lien_formula_html: "CityScroll показывает, как часто налоговые залоги на том же этапе попадали в окончательный список продажи в прошлых циклах. Это не прогноз продажи или лишения права собственности.",
    about_p_flags_intro_html: "Уведомления о закупках содержат два вида вычисленных пометок. Оба — <b>статистический контекст, а не выводы или обвинения</b>. Метка означает лишь «стоит присмотреться». За каждой формулой стоит справедливая причина. Чрезвычайные ситуации действительно случаются. Некоторые рынки специализированы, и в них мало участников. Сопоставление имён не идеально. Этот метод следует двум руководствам. Одно — <a href=\"https://www.open-contracting.org/resources/red-flags-in-public-procurement-a-guide-to-using-data-to-detect-and-mitigate-risks/\" target=\"_blank\" rel=\"noopener noreferrer\">руководство по красным флагам от Open Contracting Partnership<span class=\"sr-only\"> (открывается в новой вкладке)</span></a>. Другое — правила добросовестности <a href=\"https://opentender.eu/\" target=\"_blank\" rel=\"noopener noreferrer\">Opentender<span class=\"sr-only\"> (открывается в новой вкладке)</span></a>.",
    about_li_flags_html: "<li><b>⚑ Короткое окно объявления</b> — количество дней между публикацией уведомления и сроком подачи ответа. Мы отмечаем его, когда это 10 дней или меньше и меньше половины медианы самого ведомства. Медиана берётся из последних 200 уведомлений этого ведомства. Короткие окна дают преимущество тем, кто уже знал, что работа будет.</li><li><b>⚑ Неконкурентный метод</b> — в уведомлении говорится, что подрядчик будет выбран без полноценного конкурса. Это может быть сделка через переговоры, единственный выбранный источник, срочная закупка или пилотный проект. Иногда это оправданно. Но знать об этом всегда полезно.</li><li><b>⚑ Повторяющиеся присуждения контракта</b> — одно и то же имя подрядчика появляется в 3 или более уведомлениях о присуждении контракта в одном ведомстве в течение 90 дней. Это может указывать как на заказы-наряды в рамках рамочного контракта, так и на фаворитизм. Метка просто считает их — что это значит, решаете вы.</li><li><b>Полоса контекста</b> — насколько крупным является присуждение контракта, показанное как перцентиль присуждений этого ведомства за последние 12 месяцев (показывается только когда у ведомства 20 или более присуждений за это время). Также показывается доля подрядчика в долларах присуждений ведомства за тот же период. Мы используем точное опубликованное имя. Мы не объединяем здесь варианты написания имён.</li><li><b>Задержка принятия правил (оценка)</b> — после закрытия периода комментариев, сколько обычно требовалось похожим Agency Rules до Notice of Adoption. По истории City Record с правой цензурой, чтобы незавершённые процессы не выглядели быстрее, чем есть. По агентству при ≥20 прошлых интервалах, иначе город в целом. Показано как пунктирный сегмент “Estimate” на шкале правил и одной строкой в дайджесте только при смене полосы — никогда как подтверждённая дата. Полная формула: <a href=\"https://github.com/cityscroll/cityscroll-app/blob/main/docs/formulas/rules-adoption-lag.md\">rules adoption lag</a>.</li>",
    about_p_flags_footer_html: "Все цифры берутся вживую из <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">City Record Open Data<span class=\"sr-only\"> (открывается в новой вкладке)</span></a>, когда вы просматриваете уведомление. Это присуждения контракта <b>в том виде, как опубликованы</b>. Цифры могут отставать от регистрации контракта и фактической оплаты. Ничто здесь не говорит о том, что кто-то поступил неправильно. Это просто избавляет вас от арифметики.",
    about_h_feedback: "Отправить отзыв",
