    session_dismiss: "Скрыть",
    data_p_lede_html: "Набор данных The City Record с первого взгляда. Ваш браузер получает итоги вживую из <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">NYC Open Data<span class=\"sr-only\"> (открывается в новой вкладке)</span></a>. На сервере ничего не сохраняется. Цифры следуют <a href=\"api.html#upstream\">правилам честности</a>. Статистика остаётся в своём разделе. Вероятные ошибки ввода данных исключены — суммы от 10 млрд долларов. Заглушки сроков не считаются настоящими.",
